import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[] dp = new int[n + 1];
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int x = i;
            int best = Integer.MAX_VALUE;

            while (x > 0) {
                int d = x % 10;
                x /= 10;

                if (d > 0) {
                    best = Math.min(best, dp[i - d]);
                }
            }

            dp[i] = best + 1;
        }

        System.out.println(dp[n]);
    }
}
